.wnut{
      --bg:#17130d;--bg2:#1d1811;--panel:#211b13;--panel2:#292117;--glass:rgba(246,240,223,.032);
      --line:rgba(226,211,173,.13);--line2:rgba(226,211,173,.24);--text:#f6f0df;--dim:rgba(246,240,223,.78);
      --muted:rgba(246,240,223,.46);--moss:#93a46f;--sage:#78855f;--nut:#c9a36a;--gold:#d4b36e;
      --cyan:#8fa394;--blue:#8b9890;--red:#c8816d;--violet:#9a8a78;--ink:#17130d;--shadow:0 24px 70px rgba(0,0,0,.28);
      --radius:24px;--radius2:16px;--max:1220px;
    }.wnut *{box-sizing:border-box}.wnut{scroll-behavior:smooth}.wnut{margin:0;background:
      radial-gradient(900px 500px at 80% -10%,rgba(119,132,89,.15),transparent 62%),
      radial-gradient(700px 500px at -10% 22%,rgba(145,102,57,.12),transparent 62%),
      linear-gradient(180deg,var(--bg),#19140e 50%,#120f0a);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
      min-height:100vh}.wnut a{color:inherit;text-decoration:none}.wnut button{font:inherit}.wnut .topbar{position:sticky;top:0;z-index:20;backdrop-filter:blur(18px);background:rgba(23,19,13,.82);border-bottom:1px solid var(--line)}.wnut .topbar-inner{max-width:var(--max);margin:auto;height:62px;display:flex;align-items:center;gap:16px;padding:0 22px}.wnut .brand{font-weight:900;letter-spacing:-.03em}.wnut .brand span{color:var(--nut)}.wnut .nav{display:flex;gap:8px;margin-left:12px}.wnut .nav a{font-size:12px;color:var(--muted);padding:8px 10px;border-radius:10px}.wnut .nav a:hover{color:var(--text);background:var(--glass)}.wnut .status-pill{margin-left:auto;display:flex;align-items:center;gap:7px;padding:7px 10px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:11px;background:rgba(255,255,255,.025)}.wnut .dot{width:7px;height:7px;border-radius:50%;background:var(--muted);box-shadow:0 0 0 4px rgba(255,255,255,.03)}.wnut .dot.live{background:var(--moss);box-shadow:0 0 16px rgba(147,164,111,.42)}.wnut .dot.err{background:var(--red)}.wnut main{max-width:var(--max);margin:0 auto;padding:34px 22px 80px}.wnut .hero{position:relative;overflow:hidden;border:1px solid var(--line2);border-radius:32px;padding:38px;background:
      radial-gradient(700px 360px at 86% 16%,rgba(147,164,111,.11),transparent 60%),
      radial-gradient(500px 340px at 6% 100%,rgba(201,163,106,.12),transparent 62%),
      linear-gradient(145deg,#211b13,#2a2218 70%,#1b1610);box-shadow:var(--shadow)}.wnut .hero:after{content:"";position:absolute;right:-80px;bottom:-110px;width:390px;height:390px;border-radius:50%;border:1px solid rgba(212,179,110,.10);box-shadow:inset 0 0 0 34px rgba(212,179,110,.018),inset 0 0 0 75px rgba(212,179,110,.018)}.wnut .eyebrow{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);font-weight:800}.wnut .hero h1{margin:9px 0 4px;font-size:clamp(42px,7vw,82px);letter-spacing:-.065em;line-height:.95}.wnut .hero h1 .w{color:var(--moss)}.wnut .hero-sub{font-size:18px;color:var(--nut);font-weight:700;margin:0 0 16px}.wnut .hero-copy{max-width:710px;color:var(--dim);font-size:14px;line-height:1.75;margin:0}.wnut .chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.wnut .chip{font-size:11px;font-weight:750;padding:7px 10px;border-radius:999px;background:rgba(255,255,255,.035);border:1px solid var(--line);color:var(--dim)}.wnut .chip.accent{color:var(--moss);border-color:rgba(147,164,111,.23);background:rgba(147,164,111,.065)}.wnut .hero-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:22px}.wnut .btn{display:inline-flex;align-items:center;gap:8px;padding:10px 13px;border-radius:12px;border:1px solid var(--line2);background:var(--glass);color:var(--dim);font-weight:750;font-size:12px;cursor:pointer}.wnut .btn:hover{background:rgba(255,255,255,.07);color:var(--text)}.wnut .btn.primary{background:linear-gradient(135deg,#897343,#b79a5c);color:#17130d;border-color:transparent}.wnut .contracts{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:22px;max-width:940px}.wnut .contract{display:grid;grid-template-columns:auto 1fr auto;gap:9px;align-items:center;border:1px solid var(--line);border-radius:13px;padding:10px 11px;background:rgba(0,0,0,.12);min-width:0}.wnut .contract label{font-size:9px;color:var(--muted);font-weight:800;letter-spacing:.09em;text-transform:uppercase}.wnut .contract code{font-size:11px;color:var(--dim);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.wnut .copy{border:0;background:none;color:var(--muted);cursor:pointer;font-size:10px}.wnut .copy:hover{color:var(--moss)}.wnut .grid{display:grid;gap:18px}.wnut .g2{grid-template-columns:1.45fr .75fr}.wnut .g3{grid-template-columns:repeat(3,1fr)}.wnut .g4{grid-template-columns:repeat(4,1fr)}.wnut .section{margin-top:18px;border:1px solid var(--line);border-radius:var(--radius);background:linear-gradient(145deg,rgba(33,27,19,.97),rgba(25,20,14,.96));box-shadow:0 15px 45px rgba(0,0,0,.15);padding:24px}.wnut .section.glow{border-color:var(--line2);background:linear-gradient(145deg,rgba(43,35,24,.97),rgba(27,22,15,.96))}.wnut .section-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:18px}.wnut .section-head h2{margin:4px 0 0;font-size:20px;letter-spacing:-.025em}.wnut .section-head p{margin:5px 0 0;color:var(--muted);font-size:12px;line-height:1.55;max-width:710px}.wnut .section-tag{font-size:10px;color:var(--muted);border:1px solid var(--line);border-radius:999px;padding:6px 9px;white-space:nowrap}.wnut .metric{min-height:100px;border:1px solid var(--line);border-radius:16px;background:rgba(255,255,255,.025);padding:15px;display:flex;flex-direction:column;justify-content:space-between}.wnut .metric-label{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.065em;font-weight:850}.wnut .metric-value{font-size:23px;font-weight:900;color:var(--moss);letter-spacing:-.025em;margin-top:10px}.wnut .metric-value.nut{color:var(--nut)}.wnut .metric-value.gold{color:var(--gold)}.wnut .metric-value.blue{color:var(--blue)}.wnut .metric-sub{font-size:10px;color:var(--muted);margin-top:7px}.wnut .state-grid{display:grid;grid-template-columns:240px 1fr;gap:28px;align-items:center}.wnut .gauge{width:210px;height:210px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--moss) 0 var(--pct,0%),rgba(255,255,255,.055) var(--pct,0%) 100%);box-shadow:inset 0 0 0 1px rgba(255,255,255,.03),0 30px 60px rgba(0,0,0,.24);margin:auto}.wnut .gauge-inner{width:166px;height:166px;border-radius:50%;display:grid;place-items:center;text-align:center;background:#1a150f;border:1px solid var(--line)}.wnut .gauge-value{font-size:35px;font-weight:950;color:var(--moss);letter-spacing:-.05em}.wnut .gauge-label{font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.11em;margin-top:5px}.wnut .state-copy h3{font-size:29px;letter-spacing:-.04em;margin:0 0 8px}.wnut .state-copy p{margin:0;color:var(--dim);font-size:13px;line-height:1.75;max-width:680px}.wnut .state-copy strong{color:var(--moss)}.wnut .range-tabs{display:flex;gap:6px}.wnut .range-tabs button{border:1px solid var(--line);background:transparent;color:var(--muted);padding:6px 9px;border-radius:9px;font-size:10px;font-weight:800;cursor:pointer}.wnut .range-tabs button.active{color:var(--ink);background:var(--moss);border-color:transparent}.wnut .chartbox{height:270px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(180deg,rgba(0,0,0,.12),rgba(255,255,255,.012));position:relative;overflow:hidden}.wnut .chartbox svg{width:100%;height:100%;display:block}.wnut .legend{position:absolute;top:11px;left:12px;display:flex;gap:13px;flex-wrap:wrap}.wnut .legend span{display:flex;align-items:center;gap:6px;font-size:10px;color:var(--muted)}.wnut .legend i{width:13px;height:2px;display:block}.wnut .empty{height:100%;min-height:190px;display:grid;place-items:center;text-align:center;padding:30px}.wnut .empty strong{display:block;color:var(--dim);font-size:13px}.wnut .empty span{display:block;color:var(--muted);font-size:11px;margin-top:5px;max-width:430px;line-height:1.5}.wnut .dist-bar{height:34px;display:flex;border-radius:12px;overflow:hidden;border:1px solid var(--line);background:rgba(255,255,255,.02)}.wnut .seg{height:100%;min-width:2px;transition:filter .15s}.wnut .seg:hover{filter:brightness(1.2)}.wnut .dist-list{display:grid;grid-template-columns:1fr 1fr;gap:8px 16px;margin-top:14px}.wnut .dist-row{display:grid;grid-template-columns:10px 1fr auto;gap:8px;align-items:center;font-size:11px}.wnut .sw{width:9px;height:9px;border-radius:3px}.wnut .dist-row .name{color:var(--dim);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.wnut .dist-row .amt{text-align:right;color:var(--text);font-weight:750}.wnut .dist-row small{display:block;color:var(--muted);font-weight:500;margin-top:2px}.wnut .market-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.wnut .market{border:1px solid var(--line);border-radius:15px;padding:14px;background:rgba(255,255,255,.02)}.wnut .market-top{display:flex;justify-content:space-between;gap:10px}.wnut .market h3{font-size:13px;margin:0}.wnut .market .venue{font-size:10px;color:var(--muted)}.wnut .market-kv{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:13px}.wnut .market-kv div{padding:8px;border:1px solid var(--line);border-radius:10px}.wnut .market-kv span{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);font-weight:800}.wnut .market-kv b{display:block;font-size:12px;margin-top:4px}.wnut .market-links{display:flex;gap:7px;margin-top:11px}.wnut .market-links a{font-size:10px;color:var(--moss)}.wnut .table{width:100%;border-collapse:collapse}.wnut .table th{text-align:left;color:var(--muted);font-size:9px;letter-spacing:.08em;text-transform:uppercase;padding:0 10px 9px;border-bottom:1px solid var(--line)}.wnut .table td{padding:10px;border-bottom:1px solid rgba(255,255,255,.045);font-size:11px;color:var(--dim)}.wnut .table tr:last-child td{border-bottom:0}.wnut .mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.wnut .right{text-align:right}.wnut .event-type{display:inline-flex;align-items:center;gap:6px;font-weight:800}.wnut .event-type i{width:6px;height:6px;border-radius:50%}.wnut .event-type.wrap{color:var(--moss)}.wnut .event-type.wrap i{background:var(--moss)}.wnut .event-type.unwrap{color:var(--nut)}.wnut .event-type.unwrap i{background:var(--nut)}.wnut .event-type.transfer{color:var(--blue)}.wnut .event-type.transfer i{background:var(--blue)}.wnut .integrity{display:grid;grid-template-columns:1.2fr .8fr;gap:18px}.wnut .invariant{border:1px solid var(--line2);border-radius:18px;padding:22px;background:linear-gradient(135deg,rgba(147,164,111,.055),rgba(201,163,106,.035))}.wnut .formula{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:clamp(14px,2vw,20px);color:var(--moss);padding:18px 0}.wnut .checks{display:grid;gap:8px}.wnut .check{display:flex;align-items:center;justify-content:space-between;gap:10px;border:1px solid var(--line);border-radius:12px;padding:11px 12px;background:rgba(255,255,255,.02)}.wnut .check span{font-size:11px;color:var(--dim)}.wnut .badge{font-size:9px;font-weight:850;border:1px solid var(--line);border-radius:999px;padding:5px 7px;color:var(--muted)}.wnut .badge.ok{color:var(--moss);border-color:rgba(147,164,111,.25);background:rgba(147,164,111,.055)}.wnut .badge.warn{color:var(--gold)}.wnut .topology{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;gap:14px;align-items:center}.wnut .node{border:1px solid var(--line);border-radius:18px;padding:18px;text-align:center;background:rgba(255,255,255,.025)}.wnut .node.big{border-color:var(--line2)}.wnut .node .icon{font-size:26px}.wnut .node b{display:block;margin-top:7px;font-size:14px}.wnut .node span{display:block;color:var(--muted);font-size:10px;margin-top:4px;line-height:1.45}.wnut .arrow{font-size:23px;color:var(--muted)}.wnut .warning{border-color:rgba(217,140,123,.22);background:linear-gradient(145deg,rgba(45,25,21,.52),rgba(20,25,20,.9))}.wnut .warning h2{color:#efb09f}.wnut .warning p{font-size:12px;color:var(--dim);line-height:1.7;margin:0;max-width:820px}.wnut .warning code{color:var(--nut)}.wnut footer{max-width:var(--max);margin:auto;padding:0 22px 40px;display:flex;justify-content:space-between;gap:20px;color:var(--muted);font-size:10px}.wnut .skeleton{position:relative;overflow:hidden;color:transparent!important;background:rgba(255,255,255,.045)!important;border-radius:6px}.wnut .skeleton:after{content:"";position:absolute;inset:0;transform:translateX(-100%);background:linear-gradient(90deg,transparent,rgba(255,255,255,.06),transparent);animation:shimmer 1.6s infinite}@keyframes shimmer{100%{transform:translateX(100%)}}@media(max-width:980px){.wnut .g2, .wnut .integrity{grid-template-columns:1fr}.wnut .g4{grid-template-columns:1fr 1fr}.wnut .market-grid{grid-template-columns:1fr 1fr}.wnut .state-grid{grid-template-columns:210px 1fr}.wnut .contracts{grid-template-columns:1fr}.wnut .topology{grid-template-columns:1fr}.wnut .arrow{transform:rotate(90deg);text-align:center}}@media(max-width:680px){.wnut main{padding:22px 13px 60px}.wnut .topbar-inner{padding:0 13px}.wnut .nav{display:none}.wnut .hero{padding:25px 20px;border-radius:24px}.wnut .hero h1{font-size:52px}.wnut .g3, .wnut .g4, .wnut .market-grid, .wnut .dist-list{grid-template-columns:1fr}.wnut .state-grid{grid-template-columns:1fr}.wnut .gauge{width:190px;height:190px}.wnut .gauge-inner{width:150px;height:150px}.wnut .section{padding:18px;border-radius:20px}.wnut .section-head{flex-direction:column}.wnut .table-wrap{overflow:auto}.wnut .table{min-width:680px}.wnut .metric{min-height:86px}.wnut .status-pill{font-size:9px}.wnut footer{padding:0 13px 30px;flex-direction:column}}

script:
(() => {
  const API = '/api/wnut-data';
  const WNUT = '0xBA5ED46e31F80dafF307cbf60bd422a6f62E3dd3';
  const NUT = '0xb8DE15Fb529d98C93C749De63c749D48D25A30DF';
  const $ = id => document.getElementById(id);
  const num = v => v == null || v === '' || Number.isNaN(Number(v)) ? null : Number(v);
  const fmt = (v,d=6) => { const n=num(v); if(n==null)return '—'; if(Math.abs(n)>=1e9)return (n/1e9).toFixed(2)+'B'; if(Math.abs(n)>=1e6)return (n/1e6).toFixed(2)+'M'; if(Math.abs(n)>=1e3)return (n/1e3).toFixed(2)+'K'; if(n===0)return '0'; return n.toFixed(d).replace(/0+$/,'').replace(/\.$/,''); };
  const pct = v => num(v)==null?'—':num(v).toFixed(2).replace(/\.00$/,'')+'%';
  const usd = v => { const n=num(v); if(n==null)return '—'; if(Math.abs(n)>=1e9)return '$'+(n/1e9).toFixed(2)+'B'; if(Math.abs(n)>=1e6)return '$'+(n/1e6).toFixed(2)+'M'; if(Math.abs(n)>=1e3)return '$'+(n/1e3).toFixed(2)+'K'; return '$'+n.toFixed(n<1?6:2).replace(/0+$/,'').replace(/\.$/,''); };
  const ratio = v => num(v)==null?'—':fmt(v,6)+'×';
  const short = a => a ? a.slice(0,6)+'…'+a.slice(-4) : '—';
  const time = v => { if(!v)return '—'; try{return new Date(v).toLocaleString([], {month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit'})}catch{return '—'} };
  let data=null, range='h24';
  const palette=['#93a46f','#c9a36a','#d4b36e','#8fa394','#8b9890','#78855f','#9a8a78','#ad8266'];

  document.querySelectorAll('[data-copy]').forEach(btn => btn.addEventListener('click', async () => { try{await navigator.clipboard.writeText(btn.dataset.copy); const old=btn.textContent; btn.textContent='copied'; setTimeout(()=>btn.textContent=old,1100)}catch{} }));
  document.querySelectorAll('[data-range]').forEach(btn => btn.addEventListener('click', () => { range=btn.dataset.range; document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('active',x===btn)); renderFlows(); }));

  function setText(id,v){ const el=$(id); if(el) el.textContent=v; }
  function setStatus(mode,text){ $('liveDot').className='dot'+(mode==='live'?' live':mode==='err'?' err':''); setText('liveText',text); }

  function renderState(){
    const d=data||{}; const supply=num(d.totalSupply), backing=num(d.underlyingBalance); const wp=num(d.wrappedPctOfNut) ?? (supply!=null?supply*100:null);
    setText('wrappedPct',pct(wp)); $('gauge').style.setProperty('--pct',Math.max(0,Math.min(100,wp||0))+'%');
    setText('totalSupply',fmt(supply,8)); setText('underlyingBalance',fmt(backing,8)); setText('unwrappedNut',backing==null?'—':fmt(Math.max(0,1-backing),8));
    setText('backingRatio',ratio(d.backingRatio ?? (supply>0&&backing!=null?backing/supply:null))); setText('backingSurplus',fmt(d.backingSurplus ?? (supply!=null&&backing!=null?Math.max(0,backing-supply):null),8));
    setText('backingValueUsd',usd(d.backingValueUsd)); setText('holders',fmt(d.holders,0)); setText('updatedAt',d.lastCheckedAt?'Updated '+time(d.lastCheckedAt):'Awaiting backend'); setText('blockNumber',d.blockNumber?'Block '+Number(d.blockNumber).toLocaleString():'Block —');
    const ok = supply!=null&&backing!=null ? backing+1e-18>=supply : null; const b=$('checkBacking'); b.textContent=ok==null?'Awaiting data':ok?'Healthy':'Check'; b.className='badge '+(ok?'ok':ok===false?'warn':'');
  }

  function renderFlows(){
    const f=data?.flows?.[range]||{}; const wrapped=num(f.wrapped), unwrapped=num(f.unwrapped), gross=wrapped!=null&&unwrapped!=null?wrapped+unwrapped:null;
    setText('flowWrapped',fmt(wrapped,8)+' wNUT'); setText('flowUnwrapped',fmt(unwrapped,8)+' wNUT'); setText('flowNet',fmt(f.net,8)+' wNUT'); setText('flowTransferred',fmt(f.transferred,8)+' wNUT'); setText('flowTxCount',(f.txCount==null?'—':Number(f.txCount).toLocaleString())+' transactions'); setText('grossFlow',gross==null?'—':fmt(gross,8)+' wNUT'); setText('wrapShare',gross>0?pct(wrapped/gross*100):'—'); renderChart(data?.flows?.history||[]);
  }

  function renderChart(points){
    const box=$('flowChart'); const clean=(points||[]).filter(p=>p&&p.ts!=null); if(clean.length<2){box.innerHTML='<div class="empty"><div><strong>Flow history will appear here</strong><span>Ready for <code>flows.history[]</code> from /api/wnut-data.</span></div></div>';return}
    const W=760,H=270,P=22; const vals=clean.flatMap(p=>[num(p.wrapped)||0,num(p.unwrapped)||0,num(p.supply)||0]); const min=Math.min(...vals),max=Math.max(...vals),span=max-min||1; const x=i=>P+i/(clean.length-1)*(W-P*2); const y=v=>P+(H-P*2)-(Number(v||0)-min)/span*(H-P*2); const path=k=>clean.map((p,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(p[k]).toFixed(1)).join(' ');
    box.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${[.25,.5,.75].map(f=>`<line x1="${P}" x2="${W-P}" y1="${P+(H-P*2)*f}" y2="${P+(H-P*2)*f}" stroke="rgba(255,255,255,.05)"/>`).join('')}<path d="${path('wrapped')}" fill="none" stroke="#93a46f" stroke-width="2.4" vector-effect="non-scaling-stroke"/><path d="${path('unwrapped')}" fill="none" stroke="#c9a36a" stroke-width="2" vector-effect="non-scaling-stroke"/><path d="${path('supply')}" fill="none" stroke="#8b9890" stroke-width="1.8" stroke-dasharray="5 4" vector-effect="non-scaling-stroke"/></svg><div class="legend"><span><i style="background:#93a46f"></i>Wrapped</span><span><i style="background:#c9a36a"></i>Unwrapped</span><span><i style="background:#8b9890"></i>Supply</span></div>`;
  }

  function renderDistribution(){
    const arr=(data?.distribution||[]).filter(x=>num(x.amount)>0); setText('distCount',arr.length+' categor'+(arr.length===1?'y':'ies')); const body=$('distributionBody'); if(!arr.length){body.innerHTML='<div class="empty"><div><strong>Distribution not indexed yet</strong><span>The frontend is ready for <code>distribution[]</code>; no addresses or labels are guessed.</span></div></div>';return}
    const total=num(data.totalSupply)||arr.reduce((s,x)=>s+(num(x.amount)||0),0)||1; body.innerHTML=`<div class="dist-bar">${arr.map((x,i)=>{const p=num(x.pct)??(num(x.amount)/total*100);return `<div class="seg" title="${esc(x.label)} · ${fmt(x.amount,8)} wNUT · ${pct(p)}" style="width:${Math.max(.15,p)}%;background:${palette[i%palette.length]}"></div>`}).join('')}</div><div class="dist-list">${arr.map((x,i)=>{const p=num(x.pct)??(num(x.amount)/total*100);return `<div class="dist-row"><i class="sw" style="background:${palette[i%palette.length]}"></i><span class="name">${esc(x.label||x.category||short(x.address))}</span><span class="amt">${fmt(x.amount,8)} wNUT<small>${pct(p)}</small></span></div>`}).join('')}</div>`;
  }

  function renderMarkets(){
    const arr=data?.markets||[]; setText('marketCount',arr.length+' verified market'+(arr.length===1?'':'s')); const grid=$('marketGrid'); if(!arr.length){grid.innerHTML='<div class="empty" style="grid-column:1/-1"><div><strong>No indexed wNUT market data</strong><span>This is a valid state. Market cards appear only when the backend returns verified pools.</span></div></div>';return}
    grid.innerHTML=arr.map(m=>`<article class="market"><div class="market-top"><div><h3>${esc(m.pair||'wNUT market')}</h3><span class="venue">${esc(m.venue||'Verified venue')}</span></div><span class="badge ${m.status==='live'?'ok':''}">${esc(m.status||'verified')}</span></div><div class="market-kv"><div><span>Liquidity</span><b>${usd(m.liquidityUsd)}</b></div><div><span>24h volume</span><b>${usd(m.volume24hUsd)}</b></div><div><span>Price</span><b>${usd(m.priceUsd)}</b></div><div><span>NUT divergence</span><b>${num(m.divergenceBps)==null?'—':fmt(m.divergenceBps,1)+' bps'}</b></div></div><div class="market-links">${m.url?`<a href="${attr(m.url)}" target="_blank" rel="noopener">Trade ↗</a>`:''}${m.chartUrl?`<a href="${attr(m.chartUrl)}" target="_blank" rel="noopener">Chart ↗</a>`:''}${m.poolAddress?`<a href="https://basescan.org/address/${attr(m.poolAddress)}" target="_blank" rel="noopener">Pool ↗</a>`:''}</div></article>`).join('');
  }

  function renderHolders(){
    const arr=data?.topHolders||[]; const rows=$('holderRows'); if(!arr.length){rows.innerHTML='<tr><td colspan="5"><div class="empty" style="min-height:140px"><div><strong>No holder data yet</strong><span>Awaiting <code>topHolders[]</code>.</span></div></div></td></tr>';return}
    rows.innerHTML=arr.slice(0,12).map((h,i)=>`<tr><td>${i+1}</td><td><span>${esc(h.label||short(h.address))}</span>${h.label&&h.address?`<small style="display:block;color:var(--muted);margin-top:2px" class="mono">${short(h.address)}</small>`:''}</td><td>${esc(h.type||'wallet')}</td><td class="right">${fmt(h.balance,8)} wNUT</td><td class="right">${pct(h.pct)}</td></tr>`).join('');
  }

  function renderEvents(){
    const arr=data?.recentEvents||[]; const rows=$('eventRows'); if(!arr.length){rows.innerHTML='<tr><td colspan="4"><div class="empty" style="min-height:140px"><div><strong>No event data yet</strong><span>Awaiting <code>recentEvents[]</code>.</span></div></div></td></tr>';return}
    rows.innerHTML=arr.slice(0,12).map(e=>{const t=(e.type||'transfer').toLowerCase(); const cp=t==='wrap'?(e.to||e.from):t==='unwrap'?(e.from||e.to):(e.to||e.from);return `<tr><td><span class="event-type ${t}"><i></i>${esc(t)}</span></td><td>${fmt(e.amount,8)} wNUT</td><td class="mono"><a href="${e.txHash?'https://basescan.org/tx/'+attr(e.txHash):'#'}" target="_blank" rel="noopener">${short(cp)}</a></td><td class="right">${time(e.timestamp)}</td></tr>`}).join('');
  }

  function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function attr(s){return esc(s).replace(/`/g,'&#96;')}
  function renderAll(){renderState();renderFlows();renderDistribution();renderMarkets();renderHolders();renderEvents(); setText('footerSource',data?.lastCheckedAt?'Live wrapper data · '+time(data.lastCheckedAt):'Frontend ready · waiting for /api/wnut-data')}

  async function load(){
    setStatus('wait','Connecting to /api/wnut-data');
    try{
      const r=await fetch(API,{headers:{accept:'application/json'},cache:'no-store'}); if(!r.ok)throw new Error('HTTP '+r.status); const j=await r.json(); data=j?.wnut||j||{};
      if(data.address&&data.address.toLowerCase()!==WNUT.toLowerCase()) console.warn('Unexpected wNUT address',data.address);
      if(data.underlying&&data.underlying.toLowerCase()!==NUT.toLowerCase()) console.warn('Unexpected underlying NUT address',data.underlying);
      renderAll(); setStatus('live','Live · Base '+(data.blockNumber?'#'+Number(data.blockNumber).toLocaleString():'8453'));
    }catch(err){console.warn('wNUT frontend: backend unavailable',err); data=null; renderAll(); setStatus('err','Backend unavailable · frontend ready')}
  }
  load(); setInterval(load,300000);
})();
